result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/mascot.js", "content": "import * as THREE from 'three';

const SMILE_REGION_Y = -0.3;
const PUSH_SCALE = 0.4;

function buildMorphGeometry(geometry) {
  const pos = geometry.attributes.position;
  const count = pos.count;
  const smile = new Float32Array(count * 3);
  const frown = new Float32Array(count * 3);

  for (let i = 0; i < count; i++) {
    const y = pos.getY(i);
    if (y < SMILE_REGION_Y) {
      const dz = PUSH_SCALE * -y; // positive for negative y
      smile[i * 3 + 2] = dz;
      frown[i * 3 + 2] = -dz;
    }
    // vertices outside the region keep zero deltas (never move)
  }

  geometry.morphAttributes.position = [
    new THREE.BufferAttribute(smile, 3),
    new THREE.BufferAttribute(frown, 3),
  ];
  return geometry;
}

export function buildMascot() {
  const geometry = buildMorphGeometry(new THREE.SphereGeometry(1, 48, 32));

  const material = new THREE.MeshStandardMaterial({ morphTargets: true });
  const mesh = new THREE.Mesh(geometry, material);

  mesh.updateMorphTargets();
  // ensure the dictionary is present and ordered as specified
  mesh.morphTargetDictionary = { smile: 0, frown: 1 };
  mesh.morphTargetInfluences = [0, 0];

  return mesh;
}

/**
 * Computes base position + sum over targets of influence_k * delta_k.
 */
export function morphedPosition(mesh, vertexIndex) {
  const base = mesh.geometry.attributes.position;
  const x = base.getX(vertexIndex);
  const y = base.getY(vertexIndex);
  const z = base.getZ(vertexIndex);

  const deltas = mesh.geometry.morphAttributes.position;
  const influences = mesh.morphTargetInfluences;

  let dx = 0, dy = 0, dz = 0;
  for (let k = 0; k < deltas.length; k++) {
    const w = influences[k];
    if (w === 0) continue;
    dx += w * deltas[k].getX(vertexIndex);
    dy += w * deltas[k].getY(vertexIndex);
    dz += w * deltas[k].getZ(vertexIndex);
  }

  return new THREE.Vector3(x + dx, y + dy, z + dz);
}
