result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/mascot.test.js", "content": "import { describe, it, expect } from 'vitest';
import { buildMascot, morphedPosition } from '../src/mascot.js';

function findChinVertex(mesh) {
  // pick the lowest vertex (most negative y) in the smile/frown region
  const pos = mesh.geometry.attributes.position;
  let best = -1;
  for (let i = 0; i < pos.count; i++) {
    if (pos.getY(i) < -0.3 && (best === -1 || pos.getY(i) < pos.getY(best))) {
      best = i;
    }
  }
  return best;
}

describe('mascot morph targets', () => {
  it('morphTargetDictionary maps "smile" to 0 and "frown" to 1', () => {
    const mesh = buildMascot();
    expect(mesh.morphTargetDictionary).toEqual({ smile: 0, frown: 1 });
    expect(mesh.geometry.morphAttributes.position.length).toBe(2);
  });

  it('influences [1,0] push a chin vertex +z per formula', () => {
    const mesh = buildMascot();
    mesh.morphTargetInfluences = [1, 0];
    const i = findChinVertex(mesh);
    const baseZ = mesh.geometry.attributes.position.getZ(i);
    const y = mesh.geometry.attributes.position.getY(i);
    const z = morphedPosition(mesh, i).z;

    expect(z).toBeGreaterThan(baseZ);
    expect(z).toBeCloseTo(baseZ + 0.4 * -y, 9);
  });

  it('influences [0.5,0.5] cancel to base position within 1e-9', () => {
    const mesh = buildMascot();
    mesh.morphTargetInfluences = [0.5, 0.5];
    const pos = mesh.geometry.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      if (pos.getY(i) < -0.3) {
        const p = morphedPosition(mesh, i);
        expect(p.x).toBeCloseTo(pos.getX(i), 9);
        expect(p.y).toBeCloseTo(pos.getY(i), 9);
        expect(p.z).toBeCloseTo(pos.getZ(i), 9);
      }
    }
  });

  it('vertices with y > 0 never move for any influence combo', () => {
    const mesh = buildMascot();
    const pos = mesh.geometry.attributes.position;
    for (const [s, f] of [[1, 0], [0, 1], [0.5, 0.5], [0.7, 0.3], [1, 1]]) {
      mesh.morphTargetInfluences = [s, f];
      for (let i = 0; i < pos.count; i++) {
        if (pos.getY(i) > 0) {
          const p = morphedPosition(mesh, i);
          expect(p.x).toBe(pos.getX(i));
          expect(p.y).toBe(pos.getY(i));
          expect(p.z).toBe(pos.getZ(i));
        }
      }
    }
  });

  it('influence [0,1] mirrors [1,0] in z about the base', () => {
    const mesh = buildMascot();
    const i = findChinVertex(mesh);
    const baseZ = mesh.geometry.attributes.position.getZ(i);

    mesh.morphTargetInfluences = [1, 0];
    const zSmile = morphedPosition(mesh, i).z;

    mesh.morphTargetInfluences = [0, 1];
    const zFrown = morphedPosition(mesh, i).z;

    expect(zFrown).toBeLessThan(baseZ);
    expect(zFrown).toBeCloseTo(2 * baseZ - zSmile, 9);
  });
});
"})
